'use strict';

// MODULES //

var tape = require( 'tape' );
var isAlmostSameValue = require( '@stdlib/assert/is-almost-same-value' );
var atan = require( '@stdlib/math/base/special/atan' );
var incrnanmmaape = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof incrnanmmaape, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function throws an error if not provided a positive integer', function test( t ) {
	var values;
	var i;

	values = [
		'5',
		-5.0,
		0.0,
		3.14,
		true,
		null,
		void 0,
		NaN,
		[],
		{},
		function noop() {}
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			incrnanmmaape( value );
		};
	}
});

tape( 'the function returns an accumulator function', function test( t ) {
	t.strictEqual( typeof incrnanmmaape( 3 ), 'function', 'returns expected value' );
	t.end();
});

tape( 'the accumulator function computes a moving mean arctangent absolute percentage error incrementally', function test( t ) {
	var expected;
	var actual;
	var data;
	var acc;
	var N;
	var i;

	data = [
		[ 2.0, 3.0 ],
		[ 3.0, 1.0 ],
		[ NaN, 1.0 ],
		[ 5.0, 2.0 ],
		[ 4.0, 4.0 ],
		[ 1.0, NaN ],
		[ 3.0, 10.0 ],
		[ NaN, NaN ],
		[ 4.0, 5.0 ]
	];
	N = data.length;

	acc = incrnanmmaape( 3 );

	// Note: manually computed
	expected = [
		(1.0/1.0)*( atan(1.0/3.0) ),
		(1.0/2.0)*( atan(1.0/3.0)+atan(2.0/1.0) ),
		(1.0/2.0)*( atan(1.0/3.0)+atan(2.0/1.0) ),
		(1.0/3.0)*( atan(1.0/3.0)+atan(2.0/1.0)+atan(3.0/2.0) ),
		(1.0/3.0)*( atan(2.0/1.0)+atan(3.0/2.0)+atan(0.0/4.0) ),
		(1.0/3.0)*( atan(2.0/1.0)+atan(3.0/2.0)+atan(0.0/4.0) ),
		(1.0/3.0)*( atan(3.0/2.0)+atan(0.0/4.0)+atan(7.0/10.0) ),
		(1.0/3.0)*( atan(3.0/2.0)+atan(0.0/4.0)+atan(7.0/10.0) ),
		(1.0/3.0)*( atan(0.0/4.0)+atan(7.0/10.0)+atan(1.0/5.0) )
	];
	for ( i = 0; i < N; i++ ) {
		actual = acc( data[i][0], data[i][1] );
		t.strictEqual( isAlmostSameValue( actual, expected[i], 1 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'if not provided an input value, the accumulator function returns the current mean arctangent absolute percentage error', function test( t ) {
	var data;
	var acc;
	var i;

	data = [
		[ 2.0, 3.0 ],
		[ NaN, 1.0 ],
		[ 3.0, 5.0 ],
		[ 19.0, 10.0 ],
		[ 1.0, NaN ]
	];
	acc = incrnanmmaape( 2 );
	for ( i = 0; i < data.length; i++ ) {
		acc( data[i][0], data[i][1] );
	}
	t.strictEqual( acc(), 0.5*( atan(2.0/5.0)+atan(9.0/10.0) ), 'returns expected value' );
	t.end();
});

tape( 'if data has yet to be provided, the accumulator function returns `null`', function test( t ) {
	var acc = incrnanmmaape( 3 );
	t.strictEqual( acc(), null, 'returns expected value' );
	t.end();
});

tape( 'if only `NaN` values have been provided, the accumulator function returns `null`', function test( t ) {
	var acc = incrnanmmaape( 3 );
	acc( NaN, 1.0 );
	acc( 1.0, NaN );
	acc( NaN, NaN );
	t.strictEqual( acc(), null, 'returns expected value' );
	t.end();
});

tape( 'if provided `NaN`, the accumulator function ignores the provided values and returns the current mean arctangent absolute percentage error', function test( t ) {
	var expected;
	var acc;

	acc = incrnanmmaape( 3 );
	t.strictEqual( acc( NaN, 1.0 ), null, 'returns expected value' );

	expected = atan( 1.0/3.0 );
	t.strictEqual( isAlmostSameValue( acc( 2.0, 3.0 ), expected, 1 ), true, 'returns expected value' );
	t.strictEqual( isAlmostSameValue( acc( NaN, NaN ), expected, 1 ), true, 'returns expected value' );
	t.strictEqual( isAlmostSameValue( acc( 4.0, NaN ), expected, 1 ), true, 'returns expected value' );

	expected = 0.5 * ( atan( 1.0/3.0 )+atan( 2.0/1.0 ) );
	t.strictEqual( isAlmostSameValue( acc( 3.0, 1.0 ), expected, 1 ), true, 'returns expected value' );
	t.strictEqual( isAlmostSameValue( acc( NaN, 2.0 ), expected, 1 ), true, 'returns expected value' );
	t.strictEqual( isAlmostSameValue( acc(), expected, 1 ), true, 'returns expected value' );
	t.end();
});
